const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  let maxDistanz = 50;
  let foundField = 'NICHT GEFUNDEN';
  let allFields = [];

  // Alle property_ Felder anzeigen
  for (const key of Object.keys(data)) {
    if (key.startsWith('property_')) {
      allFields.push(key + ': ' + data[key]);
    }

    if (key.toLowerCase().includes('distanz')) {
      foundField = key + ' = ' + data[key];
      const match = String(data[key]).match(/\d+/);
      if (match) {
        maxDistanz = parseInt(match[0]);
      }
    }
  }

  results.push({
    json: {
      name: data.property_name,
      max_distanz_km: maxDistanz,
      found_field: foundField,
      all_fields: allFields.join(' | ')
    }
  });
}

return results;
